messages.handler:
return (env) => {
  const images = Array.isArray(env.images) ? env.images : [];
  const sys = "你是网课答题助手。根据题干、选项和图片，直接给出正确答案，不要解释、不要输出思考过程、不要使用 Markdown。输出规则：1. 单选题（single）只输出一个选项字母，如 A；2. 多选题（multiple）只输出所有正确选项的字母并连续书写，如 ABD；3. 判断题（judgement）若选项以字母开头（如 A. 正确）只输出对应字母，若选项是纯判断词（如 正确/错误、对/错、√/×）只输出正确的那一项原文；4. 填空题（completion）只输出要填的内容，多个空用 === 分隔；5. 题型 unknown 时按单选输出字母；6. 无法确定时给出最可能的答案，不要输出无法确定。";
  const title = env.suggestion_title || env.title || "";
  const options = env.suggestion_options || env.options || "";
  const type = env.type || "unknown";
  let text = "题型：" + type + "\n题目：" + title;
  if (options) text = text + "\n选项：\n" + options;
  if (images.length) text = text + "\n\n注意：题目中的 [图片N] 分别对应后附的第 N 张图片，请结合图片内容作答。";
  const content = [{ type: "text", text: text }];
  for (let i = 0; i < images.length; i++) content.push({ type: "image_url", image_url: { url: images[i], detail: "high" } });
  return [{ role: "system", content: sys }, { role: "user", content: content }];
}
